                @(posedge clk);
            end
            #1;
            #1;

            check_outputs(8'hCC);
        end
        endtask

    task testcase005;

        integer i;
        begin
            test_num = test_num + 1;
            $display("Testcase %0d: Walking Bit (1 followed by 7 zeros)", test_num);
            reset_dut();

            serial_in = 1'b1;
            @(posedge clk);

            serial_in = 1'b0;
            repeat(7) @(posedge clk);
            #1;
            #1;

            check_outputs(8'h80);
        end
        endtask

    task testcase006;

        begin
            test_num = test_num + 1;
