description:
Implement the Verilog module based on the following description.
We want to create a 2-bit state machine that:

// (1) transitions to the next state on a rising edge of the clock,
// (2) resets to state '00' on an asynchronous reset,
// (3) has the states '00', '01', '10', and '11',
// (4) cycles through the states in the given order.

// The state value is output on 'state[1:0]'. The reset signal is active high asynchronous.

module top_module(
    input wire clk,
    input wire reset,
    output reg [1:0] state
);

code:
module top_module(
    input wire clk,
    input wire reset,
    output reg [1:0] state
);

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state <= 2'b00;
        end else begin
            case (state)
                2'b00: state <= 2'b01;
                2'b01: state <= 2'b10;
                2'b10: state <= 2'b11;
                2'b11: state <= 2'b00;
            endcase
        end
    end

endmodule

