module top_module(
    input a,
    input b,
    input sel_b1,
    input sel_b2,
    output reg out_always
);reg mux_out1, mux_out2;

always @(posedge sel_b1 or posedge sel_b2) begin
    mux_out1 <= a;
    mux_out2 <= b;
end

always @(posedge sel_b1 or posedge sel_b2) begin
    if(sel_b1 & sel_b2) begin
        out_always <= mux_out2;
    end else begin
        out_always <= mux_out1;
    end
end

endmodule

module fsm (
    input clk,
    input reset,
    input a,
    output reg z);

    parameter A=0, B=1, C=2;
    reg [1:0] state, next;

    always @(posedge clk) begin
        if (reset) state <= A;
        else state <= next;
    end

    always_comb begin
        case (state)
            A: next = a ? B : A;
            B: next = a ? B : C;
            C: next = a ? B : A;
            default: next = 'x;
        endcase
    end

    assign z = (state == C);

endmodule

