description:
Design a clock divider that generates two output clock signals from a single input clock. The first output, clk_out1, toggles every 12 clock cycles of clk_in, while the second output, clk_out2, toggles every 50 million clock cycles of clk_in. The module utilizes two counters to create the respective divided clock frequencies, enabling clock management for digital systems requiring different timing signals.
module top_module(
    clk_in,
    clk_out1,
    clk_out2
);

code:
module top_module(
    clk_in,
    clk_out1,
    clk_out2
);input clk_in;
    output clk_out1;
    output clk_out2;

    reg [24:0] counter1 = 0;
    reg [29:0] counter2 = 0;

    assign clk_out1 = counter1[24];
    assign clk_out2 = counter2[29];

    always @(posedge clk_in) begin
        if (counter1 == 24'd0) begin
            counter1 <= 24'd11;
        end else begin
            counter1 <= counter1 - 1;
        end

        if (counter2 == 30'd0) begin
            counter2 <= 30'd49_999_999;
        end else begin
            counter2 <= counter2 - 1;
        end
    end

endmodule

