module top_module(
    input clk,
    input areset,  // async active-high reset to zero
    input load,
    input ena,
    input [7:0] input1,
    input [7:0] input2,
    input [7:0] input3,
    input [7:0] input4,
    input sel_b1,
    input sel_b2,
    output reg [7:0] out_always
);// 4-to-1 Multiplexer
wire [7:0] mux_out;
assign mux_out = (sel_b1 == 0 && sel_b2 == 0) ? input1 :
                 (sel_b1 == 0 && sel_b2 == 1) ? input2 :
                 (sel_b1 == 1 && sel_b2 == 0) ? input3 :
                                               input4;

// 4-bit Shift Register
reg [3:0] shift_reg;
always @(posedge clk, negedge areset) begin
    if (~areset) begin
        shift_reg <= 4'b0;
    end else if (load) begin
        shift_reg <= mux_out;
    end else if (ena) begin
        if (sel_b1 == 0 && sel_b2 == 0) begin
            shift_reg <= {shift_reg[2:0], mux_out[7]};
        end else if (sel_b1 == 0 && sel_b2 == 1) begin
            shift_reg <= {shift_reg[1:0], mux_out[7:6]};
        end else if (sel_b1 == 1 && sel_b2 == 0) begin
            shift_reg <= {shift_reg[3:1], mux_out[7]};
        end else begin
            shift_reg <= {mux_out[6:3], shift_reg[0]};
        end
    end
end

// Additional Functional Module
reg [7:0] func_out;
always @(posedge clk) begin
    func_out <= mux_out + shift_reg;
end

// Output
always @(*) begin
    out_always = func_out;
end

endmodule

