module top_module(
    input aclr,
    input [39:0] data,
    input rdclk,
    input rdreq,
    input wrclk,
    input wrreq,
    output reg [39:0] q, // Changed from wire to reg
    output rdempty,
    output [4:0] rdusedw,
    output wrfull,
    output [4:0] wrusedw
    );parameter WIDTH = 40;
    parameter DEPTH = 32;
    parameter ADDR_WIDTH = 5;

    reg [WIDTH-1:0] mem [0:DEPTH-1];
    reg [ADDR_WIDTH-1:0] wr_ptr;
    reg [ADDR_WIDTH-1:0] rd_ptr;
    reg [ADDR_WIDTH-1:0] usedw;
    wire full = (usedw == DEPTH);
    wire empty = (usedw == 0);

    assign wrfull = full;
    assign rdempty = empty;
    assign wrusedw = usedw;
    assign rdusedw = usedw;

    always @(posedge wrclk or negedge aclr) begin
        if (~aclr) begin
            wr_ptr <= 0;
            usedw <= 0;
        end else if (wrreq && ~full) begin
            mem[wr_ptr] <= data;
            wr_ptr <= wr_ptr + 1;
            usedw <= usedw + 1;
        end
    end

    always @(posedge rdclk or negedge aclr) begin
        if (~aclr) begin
            rd_ptr <= 0;
            usedw <= 0;
            q <= 0; // Reset q to a known state
        end else if (rdreq && ~empty) begin
            q <= mem[rd_ptr];
            rd_ptr <= rd_ptr + 1;
            usedw <= usedw - 1;
        end
    end
endmodule

