module top_module(
    input clk,                  // Clock signal
    input reset,                // Synchronous active-high reset
    input [7:0] data_in,        // Data input for the shift register
    input a,                    // Input signal for XOR gate
    input b,                    // Input signal for XOR gate
    input control,              // Control signal for the tri-state buffer
    output [7:0] shift_out,     // 8-bit output from the shift register
    output xor_out,             // Output from the XOR gate
    output [7:0] final_out      // Final output from the functional module
);reg [7:0] shift_reg;
wire xor_out_internal; // Changed the name to avoid conflict
wire [7:0] functional_in;

// Shift register
always @(posedge clk) begin
    if (reset) begin
        shift_reg <= 8'b0;
    end else begin
        shift_reg <= {shift_reg[6:0], data_in};
    end
end

assign shift_out = shift_reg;

// XOR gate
assign xor_out_internal = a ^ b;

// Tri-state buffer
assign functional_in = {shift_reg, xor_out_internal};
assign final_out = (control) ? 8'bz : functional_in;

assign xor_out = xor_out_internal; // Assign the internal wire to the output

endmodule

