	if (!reset) begin
		random <= 8'd100; 
		count <= 0;
	end  else if(enable) begin
		random <= {random[6:0], feedback};
		count <= count + 1;

		if (count == 8)  begin
	  		count <= 0;
	  		random_done <= random; 
		end
	end
end

assign rnd = random_done;

endmodule

