   always @(posedge clock) begin
      if (wren_a) ram[address_a] <= data_a;
      if (rden_a) q_a <= ram[address_a]; // q_a is now a valid l-value
      if (wren_b) ram[address_b] <= data_b;
      if (rden_b) q_b <= ram[address_b]; // q_b is now a valid l-value
   end

endmodule

