    Cin ,
    En  ,
    S   ,
    Cout
);input  [3:0] A   ;
    input  [3:0] B   ;
    input        Cin ;
    input        En  ;
    output [3:0] S   ;
    output       Cout;

    wire [3:0] sum;
    wire [3:0] carry;

