module top_module(
  input [n-1:0] req,
  output reg [m-1:0] grant // Changed to reg type
);parameter n = 4; // number of request signals
parameter m = 2; // number of grant signals
parameter p = 3; // number of priority levels

reg [n-1:0] priority_levels [0:p-1];

always @(*) begin
  // Calculate priority levels based on requests
  priority_levels[0] = req & ~{priority_levels[1], priority_levels[2]};
  priority_levels[1] = req & priority_levels[0];
  priority_levels[2] = req & priority_levels[1];
end

always @(*) begin
  // Grant signals based on priority levels
  grant[0] = priority_levels[0][0] & ~grant[1]; // Access specific bits instead of arrays
  grant[1] = priority_levels[1][0] & ~grant[0]; // Access specific bits instead of arrays
end

endmodule

