description:
Design a clock divider module that takes a clock input (CLKI) and generates a divided output (CDIVX) based on a configurable division factor specified through the parameter DIV. The module features asynchronous reset (RST) functionality to initialize the count and output, and includes alignment control (ALIGNWD) for fine-tuning the timing behavior. The division factor is set during initialization, allowing for division by 2, 4, or 8, while the output toggles its state every time the internal count reaches the specified division threshold. The module is ideal for generating lower frequency clocks from a higher frequency input clock signal.
module top_module(
	input CLKI, RST, ALIGNWD,
	output CDIVX
);

code:
module top_module(
	input CLKI, RST, ALIGNWD,
	output CDIVX
);parameter GSR = "DISABLED";
	parameter DIV = "2.0";

	reg [1:0] count;
	reg [1:0] div_factor;
	reg out_reg;

	always @(posedge CLKI or posedge RST) begin
		if(RST) begin
			count <= 2'b00;
			out_reg <= 1'b0;
		end
		else begin
			if(GSR == "ENABLED" && ALIGNWD == 1'b0) begin
				count <= 2'b00;
				out_reg <= 1'b0;
			end
			else begin
				count <= count + 1;
				if(count == div_factor) begin
					count <= 2'b00;
					out_reg <= ~out_reg;
				end
			end
		end
	end

	assign CDIVX = out_reg;

	// Set div_factor based on DIV parameter
	initial begin
		case(DIV)
			"2.0": div_factor = 2'b01;
			"4.0": div_factor = 2'b10;
			"8.0": div_factor = 2'b11;
			default: div_factor = 2'b01;
		endcase
	end
endmodule

